/// If we want to add an xattr to the inode, we should make sure that
/// i_extra_isize is not 0 and that the inode size is not less than
/// EXT4_GOOD_OLD_INODE_SIZE + extra_isize + pad.
///   EXT4_GOOD_OLD_INODE_SIZE   extra_isize header   entry   pad  data
/// |--------------------------|------------|------|---------|---|-------|
macro_rules! EXT4_INODE_HAS_XATTR_SPACE__2 {
($inode:expr) => {
{
let __v: bool = ((unsafe { (*EXT4_I!($inode)).i_extra_isize }) as i32) != 0 && (128i32.wrapping_add((unsafe { (*EXT4_I!($inode)).i_extra_isize }) as i32) as u64).wrapping_add(core::mem::size_of::<ext4_xattr_ibody_header>() as u64).wrapping_add(4u64) <= (EXT4_INODE_SIZE!(unsafe { (*$inode).i_sb }) as u64);
__v
}
};
}

