// macro tricks to expand the set_buffer_foo(), clear_buffer_foo()
// and buffer_foo() functions.
// To avoid reset buffer flags that are already set, because that causes
// a costly cache line transition, check the flag first.
// test_set_buffer_foo() and test_clear_buffer_foo()
#[inline(always)]
fn buffer_dirty(bh: *const buffer_head) -> i32 {
test_bit__2!(1i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn buffer_locked(bh: *const buffer_head) -> i32 {
test_bit__2!(2i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn set_buffer_mapped(bh: *mut buffer_head) {
if test_bit__3!(4i32, unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) == 0 {
set_bit(4i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}
}

#[inline(always)]
fn buffer_mapped(bh: *const buffer_head) -> i32 {
test_bit__2!(4i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn set_buffer_new(bh: *mut buffer_head) {
if test_bit__3!(5i32, unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) == 0 {
set_bit(5i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}
}

#[inline(always)]
fn clear_buffer_new(bh: *mut buffer_head) {
clear_bit(5i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn buffer_new(bh: *const buffer_head) -> i32 {
test_bit__2!(5i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn set_buffer_delay(bh: *mut buffer_head) {
if test_bit__3!(8i32, unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) == 0 {
set_bit(8i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}
}

#[inline(always)]
fn clear_buffer_delay(bh: *mut buffer_head) {
clear_bit(8i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn buffer_delay(bh: *const buffer_head) -> i32 {
test_bit__2!(8i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn buffer_write_io_error(bh: *const buffer_head) -> i32 {
test_bit__2!(10i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn clear_buffer_unwritten(bh: *mut buffer_head) {
clear_bit(11i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn buffer_unwritten(bh: *const buffer_head) -> i32 {
test_bit__2!(11i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

#[inline(always)]
fn clear_buffer_meta(bh: *mut buffer_head) {
clear_bit(13i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn clear_buffer_prio(bh: *mut buffer_head) {
clear_bit(14i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn set_buffer_uptodate(bh: *mut buffer_head) {
// If somebody else already set this uptodate, they will
// have done the memory barrier, and a reader will thus
// see *some* valid buffer state.
//
// Any other serialization (with IO errors or whatever that
// might clear the bit) has to come from other state (eg BH_Lock).
if test_bit__3!(0i32, unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) != 0 {
return;
}
// make it consistent with folio_mark_uptodate
// pairs with smp_load_acquire in buffer_uptodate
smp_mb__before_atomic!();
set_bit(0i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64);
}

#[inline(always)]
fn buffer_uptodate(bh: *const buffer_head) -> i32 {
// make it consistent with folio_test_uptodate
// pairs with smp_mb__before_atomic in set_buffer_uptodate
test_bit_acquire!(0i32, unsafe { core::ptr::addr_of!((*bh).b_state) })
}

fn get_bh(bh: *mut buffer_head) {
atomic_inc(unsafe { core::ptr::addr_of_mut!((*bh).b_count) });
}

fn put_bh(bh: *mut buffer_head) {
smp_mb__before_atomic!();
atomic_dec(unsafe { core::ptr::addr_of_mut!((*bh).b_count) });
}

fn brelse(bh: *mut buffer_head) {
if !bh.is_null() {
unsafe { __brelse(bh) };
}
}

fn getblk_unmovable(bdev: *mut block_device, block: u64, size: u32) -> *mut buffer_head {
let mut gfp: u32 = mapping_gfp_constraint((unsafe { (*bdev).bd_mapping }) as *const address_space, !(BIT!(7i32) as u32));
let __v0: u32 = gfp;
gfp = __v0 | (BIT!(15i32) as u32);
unsafe { bdev_getblk(bdev, block, size, gfp) }
}

fn __getblk(bdev: *mut block_device, block: u64, size: u32) -> *mut buffer_head {
let mut gfp: u32 = mapping_gfp_constraint((unsafe { (*bdev).bd_mapping }) as *const address_space, !(BIT!(7i32) as u32));
let __v0: u32 = gfp;
gfp = __v0 | ((BIT!(3i32) as u32) | (BIT!(15i32) as u32));
unsafe { bdev_getblk(bdev, block, size, gfp) }
}

fn sb_getblk(sb: *mut super_block, block: u64) -> *mut buffer_head {
__getblk(unsafe { (*sb).s_bdev }, block, (unsafe { (*sb).s_blocksize }) as u32)
}

fn sb_find_get_block(sb: *mut super_block, block: u64) -> *mut buffer_head {
unsafe { __find_get_block((*sb).s_bdev, block, (*sb).s_blocksize as u32) }
}

fn map_bh(bh: *mut buffer_head, sb: *mut super_block, block: u64) {
set_buffer_mapped(bh);
unsafe {
(*bh).b_bdev = (*sb).s_bdev;
}
unsafe {
(*bh).b_blocknr = block;
}
unsafe {
(*bh).b_size = (*sb).s_blocksize;
}
}

fn wait_on_buffer(bh: *mut buffer_head) {
might_sleep!();
if buffer_locked(bh as *const buffer_head) != 0 {
unsafe { __wait_on_buffer(bh) };
}
}

fn trylock_buffer(bh: *mut buffer_head) -> i32 {
likely!(!test_and_set_bit_lock(2i64, (unsafe { core::ptr::addr_of_mut!((*bh).b_state) }) as *mut u64)) as i32
}

fn lock_buffer(bh: *mut buffer_head) {
might_sleep!();
if trylock_buffer(bh) == 0 {
unsafe { __lock_buffer(bh) };
}
}

