fn ext4_encode_extra_time(mut ts: timespec64) -> u32 {
let extra: u32 = (ts.tv_sec.wrapping_sub((ts.tv_sec as i32) as i64) >> 32i32 & 3i64) as u32;
((extra as i64) | ts.tv_nsec << 2i32) as u32
}

fn ext4_decode_extra_time(base: u32, extra: u32) -> timespec64 {
let mut ts: timespec64 = {
let mut __t0: timespec64 = unsafe { core::mem::zeroed() };
__t0.tv_sec = (base as i32) as i64;
__t0
};
if unlikely__3!(extra & 3u32) != 0 {
ts.tv_sec = (ts.tv_sec as u64).wrapping_add(((extra & 3u32) as u64) << 32i32) as i64;
}
ts.tv_nsec = (((extra as u64) & 18446744073709551612u64) >> 2i32) as i64;
return ts;
}

